// ============================================================================
// SABIL GUARD — Phase 1: Trust Score engine.
//
// HONESTY NOTE (see the Phase 0 report): this project has no backend, no
// database, and no cron infrastructure. Everything below is a faithful
// client-side SIMULATION of the spec — real rule logic and real arithmetic,
// but "storage" is an in-memory JS array standing in for a `risk_assessments`
// table, and there is no server-side enforcement of any of it. The shapes
// (GUARD_RULES, a risk_assessment record, a devices entry) are deliberately
// close to what real DB tables/config rows would look like, so a future
// backend port is a data-migration exercise, not a redesign.
//
// Per the governing rules: default mode is "observe" — this module never
// blocks a booking or changes the customer's path in this phase. It only
// computes a score and exposes it to the agency.
// ============================================================================

const GUARD_MODE_DEFAULT = "observe"; // "observe" | "enforce" — per-agency in a real system; global here

// Configurable rule weights + on/off — stands in for an admin-editable settings table.
// Positive weight = raises risk, negative = lowers it (good-history bonus).
const GUARD_RULES_DEFAULT = {
  nameMismatch: { enabled: true, weight: 40, labelKey: "guardRuleNameMismatch" },
  faceMatchFail: { enabled: true, weight: 40, labelKey: "guardRuleFaceMatchFail" },
  duplicateDevice: { enabled: true, weight: 35, labelKey: "guardRuleDuplicateDevice" },
  newCustomerHighValue: { enabled: true, weight: 15, labelKey: "guardRuleNewCustomerHighValue" },
  lastMinuteBooking: { enabled: true, weight: 10, labelKey: "guardRuleLastMinuteBooking" },
  noCardGuarantee: { enabled: true, weight: 20, labelKey: "guardRuleNoCardGuarantee" },
  thirdPartyBooking: { enabled: true, weight: 25, labelKey: "guardRuleThirdPartyBooking" },
  pastDelayHistory: { enabled: true, weight: 15, labelKey: "guardRulePastDelayHistory" },
  onTimeHistoryBonus: { enabled: true, weight: -10, labelKey: "guardRuleOnTimeHistoryBonus" },
  appPulseSignal: { enabled: true, weight: 12, labelKey: "guardRuleAppPulseSignal" },
};

// 0–39 low, 40–69 medium, 70+ high — editable, not hardcoded into the logic below.
const GUARD_THRESHOLDS_DEFAULT = { medium: 40, high: 70 };

// A tiny non-cryptographic hash — enough to fingerprint a browser session for the
// simulation. A real backend would hash real device signals server-side.
function simpleHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (h << 5) - h + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(16);
}

// Stands in for the `devices` table: hashed fingerprint -> set of phone numbers
// seen on it. Never stores raw device data, only the hash, matching the privacy rule.
function computeDeviceFingerprint() {
  if (typeof navigator === "undefined") return "unknown-device";
  const raw = [navigator.userAgent, navigator.language, screen?.width, screen?.height, navigator.hardwareConcurrency].join("|");
  return simpleHash(raw);
}

// The core scoring function — pure, testable, and independent of React state.
// `ctx` carries only signals SABILCAR already has; it asks the customer for nothing new.
function computeRiskAssessment(ctx, rules = GUARD_RULES_DEFAULT, thresholds = GUARD_THRESHOLDS_DEFAULT) {
  let score = 0;
  const reasons = [];
  const add = (ruleKey, hit) => {
    const rule = rules[ruleKey];
    if (rule && rule.enabled && hit) {
      score += rule.weight;
      reasons.push({ key: ruleKey, labelKey: rule.labelKey, weight: rule.weight });
    }
  };

  add("nameMismatch", ctx.nameMismatch);
  add("faceMatchFail", ctx.faceMatchFail);
  add("duplicateDevice", ctx.duplicateDevice);
  add("newCustomerHighValue", ctx.isNewCustomer && ctx.carPrice >= 350 && ctx.days >= 4);
  add("lastMinuteBooking", ctx.hoursUntilPickup != null && ctx.hoursUntilPickup < 3);
  add("noCardGuarantee", ctx.paymentMethod === "cash");
  add("thirdPartyBooking", ctx.isThirdPartyDriver === true);
  add("pastDelayHistory", (ctx.pastDelayCount || 0) > 0);
  add("onTimeHistoryBonus", (ctx.pastOnTimeCount || 0) >= 2 && (ctx.pastDelayCount || 0) === 0);
  add("appPulseSignal", ctx.pulseWeak === true);

  score = Math.max(0, Math.min(100, score));
  const level = score >= thresholds.high ? "high" : score >= thresholds.medium ? "medium" : "low";
  return { score, level, reasons, computedAt: Date.now() };
}

// Stands in for a `devices` table: { deviceHash -> Set(phone numbers seen on it) }.
// Module-level (resets on reload) since there is no real persistence layer here.
const DEVICE_REGISTRY = new Map();
function checkAndRecordDevice(deviceHash, phone) {
  if (!phone) return false; // guests have no phone to cross-check against
  const seen = DEVICE_REGISTRY.get(deviceHash);
  const isDuplicate = !!seen && seen.size > 0 && !seen.has(phone);
  const next = seen ? new Set(seen) : new Set();
  next.add(phone);
  DEVICE_REGISTRY.set(deviceHash, next);
  return isDuplicate;
}

