// ============================================================================
// Fleet maintenance tracking. Three items are annual, date-based renewals
// (insurance, vignette, technical control — "الزيارة التقنية"), and three are
// wear-based, tied to mileage (oil, tires, brakes). Real due dates/mileages
// aren't in this prototype's data, so each car's schedule is derived
// deterministically from its id (a stand-in for a real `maintenance_schedule`
// table) — this gives a realistic, varied mix of overdue/due-soon/ok items
// across the fleet rather than everything lining up identically.
// ============================================================================

const MAINTENANCE_TYPES = [
  { key: "insurance", labelKey: "maintInsurance", icon: ShieldCheck, basis: "days", interval: 365, soonWindow: 21 },
  { key: "vignette", labelKey: "maintVignette", icon: FileCheck2, basis: "days", interval: 365, soonWindow: 21 },
  { key: "technicalControl", labelKey: "maintTechnicalControl", icon: ClipboardCheck, basis: "days", interval: 365, soonWindow: 30 },
  { key: "oilChange", labelKey: "maintOilChange", icon: Droplets, basis: "km", interval: 10000, soonWindow: 1000 },
  { key: "tires", labelKey: "maintTires", icon: Gauge, basis: "km", interval: 40000, soonWindow: 2000 },
  { key: "brakes", labelKey: "maintBrakes", icon: AlertTriangle, basis: "km", interval: 25000, soonWindow: 1500 },
];

// A standard GLSL-style hash: turns two integers into a well-mixed pseudo-random float in
// [0,1). A simple linear formula (car.id * a + i * b) % 100 was tried first and turned out
// to cluster badly — it flagged nearly the whole fleet as overdue on 6 items/car. This one
// actually spreads uniformly.
function hash01(a, b) {
  const x = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453;
  return x - Math.floor(x);
}

function getMaintenanceSchedule(car) {
  const DAY_MS = 24 * 60 * 60 * 1000;
  const now = Date.now();
  // ~4% overdue chance per (car, item) — with 6 items/car that puts roughly a quarter of a
  // real fleet's cars at "needs attention", which reads as realistic rather than alarming.
  const OVERDUE_P = 0.04;
  return MAINTENANCE_TYPES.map((type, i) => {
    const h = hash01(car.id, i);
    if (type.basis === "days") {
      const daysRemaining = Math.round((h - OVERDUE_P) * (type.interval / (1 - OVERDUE_P)));
      const dueDate = new Date(now + daysRemaining * DAY_MS);
      const status = daysRemaining < 0 ? "overdue" : daysRemaining <= type.soonWindow ? "soon" : "ok";
      return { ...type, remaining: daysRemaining, dueDate, status };
    }
    const kmRemaining = Math.round((h - OVERDUE_P) * (type.interval / (1 - OVERDUE_P)));
    const status = kmRemaining < 0 ? "overdue" : kmRemaining <= type.soonWindow ? "soon" : "ok";
    return { ...type, remaining: kmRemaining, status };
  });
}

