const LanguageContext = React.createContext({ lang: "ar", setLang: () => {} });
function useLang() {
  const ctx = useContext(LanguageContext);
  const t = (key) => TRANSLATIONS[ctx.lang]?.[key] ?? TRANSLATIONS.ar[key] ?? key;
  const dir = LANGUAGES.find((l) => l.id === ctx.lang)?.dir || "rtl";
  return { lang: ctx.lang, setLang: ctx.setLang, t, dir };
}

