// Genuinely reflects the browser's connection state (not staged) — try switching your
// device to airplane mode while using the app to see the banner appear for real.
function useOnlineStatus() {
  const [online, setOnline] = useState(typeof navigator !== "undefined" ? navigator.onLine : true);
  useEffect(() => {
    const goOnline = () => setOnline(true);
    const goOffline = () => setOnline(false);
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);
  return online;
}

function OfflineBanner() {
  return (
    <div className="flex items-center justify-center gap-2 py-2" style={{ background: COLOR.clay }}>
      <WifiOff size={13} color={COLOR.white} />
      <span className="text-xs font-bold" style={{ color: COLOR.white }}>لا يوجد اتصال بالإنترنت — بعض الميزات قد ما تخدمش</span>
    </div>
  );
}

// Catches unexpected render crashes so the person sees a recoverable screen instead of a
// blank white app.
class AppErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  render() {
    if (this.state.hasError) {
      return (
        <div className="flex flex-col items-center justify-center text-center px-8" style={{ width: "100%", height: "100%", background: COLOR.sand }}>
          <XOctagon size={36} color={COLOR.danger} />
          <h2 className="font-black text-base mt-4" style={{ color: COLOR.clay }}>حدث خطأ غير متوقع</h2>
          <p className="text-sm mt-1" style={{ color: COLOR.clayFaint }}>عاود حاول، وإلا استمر المشكل تواصل مع الدعم</p>
          <button
            onClick={() => this.setState({ hasError: false })}
            className="mt-5 px-5 py-2.5 rounded-xl flex items-center gap-2 text-sm font-bold"
            style={{ background: COLOR.indigo, color: COLOR.white }}
          >
            <RefreshCw size={14} />
            إعادة المحاولة
          </button>
        </div>
      );
    }
    return this.props.children;
  }
}

function daysBetween(a, b) {
  if (!a || !b) return [];
  const lo = Math.min(a, b);
  const hi = Math.max(a, b);
  const out = [];
  for (let d = lo; d <= hi; d++) out.push(d);
  return out;
}

function effectivePrice(car) {
  if (!car.seasonalPricing) return car.price;
  return Math.round(car.price * (1 + car.seasonalPricing.pct));
}

function ZelligePattern({ id, stroke = COLOR.saffron, opacity = 0.16 }) {
  return (
    <svg width="100%" height="100%" style={{ position: "absolute", inset: 0 }}>
      <defs>
        <pattern id={id} width="46" height="46" patternUnits="userSpaceOnUse">
          <g transform="translate(23,23)" fill="none" stroke={stroke} strokeWidth="1" opacity={opacity}>
            <rect x="-13" y="-13" width="26" height="26" />
            <rect x="-13" y="-13" width="26" height="26" transform="rotate(45)" />
          </g>
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill={`url(#${id})`} />
    </svg>
  );
}

