const CAR_COLOR_HEX = {
  "أبيض": "#F2F0EA",
  "أحمر": "#B23A2E",
  "أزرق": "#33507A",
  "أسود": "#1C1C1E",
  "رمادي غامق": "#3A3B40",
  "رمادي": "#8A8C92",
  "فضي": "#C7C9CC",
};

// A real per-car visual: silhouette shape varies by body type, fill reflects the car's actual
// color field — replacing a single generic icon repeated identically on every listing.
function CarSilhouette({ type, color, size = 60 }) {
  const fill = CAR_COLOR_HEX[color] || "#8A8C92";
  const isDark = ["أسود", "رمادي غامق", "أزرق", "أحمر"].includes(color);
  const windowTint = isDark ? "rgba(255,255,255,0.12)" : "rgba(0,0,0,0.28)";
  const outline = isDark ? "rgba(255,255,255,0.15)" : "rgba(0,0,0,0.12)";
  const bodyPath =
    type === "SUV"
      ? "M6,40 L9,24 Q12,14 28,13 L46,6 Q58,2 76,5 L100,11 Q116,15 120,26 L120,40 Z"
      : type === "فاخرة"
      ? "M4,37 L12,24 Q17,13 36,11 L54,5 Q70,1 90,5 L114,13 Q124,17 122,28 L122,37 Z"
      : "M7,38 L10,25 Q13,16 30,14 L47,9 Q59,6 74,9 L92,14 Q104,18 106,28 L106,38 Z";
  const windowLine =
    type === "SUV"
      ? "M28,13 Q42,7 58,7 Q72,7 84,12"
      : type === "فاخرة"
      ? "M36,11 Q58,4 78,4 Q92,5 104,12"
      : "M30,14 Q44,9 60,9 Q70,9 80,13";
  const w = type === "فاخرة" ? 130 : type === "SUV" ? 128 : 114;
  return (
    <svg viewBox={`0 0 ${w} 56`} width={size} height={size * 0.43}>
      <ellipse cx={w / 2} cy="47" rx={w / 2 - 10} ry="3.5" fill="#000" opacity="0.13" />
      <path d={bodyPath} fill={fill} stroke={outline} strokeWidth="1" />
      <path d={windowLine} fill="none" stroke={windowTint} strokeWidth="9" strokeLinecap="round" opacity="0.9" />
      <circle cx={w * 0.26} cy="39" r="8" fill="#111214" />
      <circle cx={w * 0.26} cy="39" r="3.4" fill="#6B6D72" />
      <circle cx={w * 0.77} cy="39" r="8" fill="#111214" />
      <circle cx={w * 0.77} cy="39" r="3.4" fill="#6B6D72" />
    </svg>
  );
}


// Scales to many more Moroccan cities later: only main cities show by default, and clicking
// a main city that has minor communes expands a second row to pick one precisely.
function CityPicker({ selectedCity, onSelect }) {
  const activeGroup = CITY_GROUPS.find((g) => g.name === selectedCity || g.subCities.includes(selectedCity));
  const [expandedGroup, setExpandedGroup] = useState(activeGroup?.subCities.length ? activeGroup.name : null);
  const shownSubGroup = CITY_GROUPS.find((g) => g.name === expandedGroup);

  return (
    <div>
      <div className="flex gap-2 overflow-x-auto tariq-scroll pb-1">
        {CITY_GROUPS.map((g) => {
          const isActive = selectedCity === g.name || g.subCities.includes(selectedCity);
          return (
            <Chip
              key={g.name}
              active={isActive}
              onClick={() => {
                if (g.subCities.length > 0) {
                  setExpandedGroup((prev) => (prev === g.name ? null : g.name));
                  if (!isActive) onSelect(g.name);
                } else {
                  setExpandedGroup(null);
                  onSelect(g.name);
                }
              }}
            >
              {g.name}
              {g.subCities.length > 0 ? (expandedGroup === g.name ? " ▲" : " ▼") : ""}
            </Chip>
          );
        })}
      </div>
      {shownSubGroup && shownSubGroup.subCities.length > 0 && (
        <div className="flex gap-2 overflow-x-auto tariq-scroll pb-1 mt-2 pr-3" style={{ borderRight: `2px solid ${COLOR.sandDeep}` }}>
          {shownSubGroup.subCities.map((sc) => (
            <Chip key={sc} active={selectedCity === sc} onClick={() => onSelect(sc)}>{sc}</Chip>
          ))}
        </div>
      )}
    </div>
  );
}

