// A stylized mock GPS map (streets grid + curved route + moving car) shown to both sides of a
// delivery: the driver sees "agency → customer", the customer sees the same trip from their end.
function LiveMapView({ id, progress }) {
  const points = [
    { x: 268, y: 36 },
    { x: 150, y: 108 },
    { x: 40, y: 62 },
  ];
  const t = Math.max(0, Math.min(1, progress));
  let pos;
  if (t <= 0.5) {
    const lt = t / 0.5;
    pos = { x: points[0].x + (points[1].x - points[0].x) * lt, y: points[0].y + (points[1].y - points[0].y) * lt };
  } else {
    const lt = (t - 0.5) / 0.5;
    pos = { x: points[1].x + (points[2].x - points[1].x) * lt, y: points[1].y + (points[2].y - points[1].y) * lt };
  }
  const pathD = `M${points[0].x},${points[0].y} Q${points[1].x},${points[1].y} ${points[2].x},${points[2].y}`;

  return (
    <svg viewBox="0 0 320 150" style={{ width: "100%", height: 150, borderRadius: 16, display: "block", background: COLOR.sandDeep, transition: "opacity 0.3s" }}>
      <defs>
        <linearGradient id={`${id}-route`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%" stopColor={COLOR.saffronDeep} />
          <stop offset="100%" stopColor={COLOR.saffron} />
        </linearGradient>
      </defs>
      <g stroke={COLOR.sand} strokeWidth="2" opacity="0.7">
        <line x1="0" y1="25" x2="320" y2="30" />
        <line x1="0" y1="85" x2="320" y2="90" />
        <line x1="0" y1="135" x2="320" y2="130" />
        <line x1="55" y1="0" x2="60" y2="150" />
        <line x1="145" y1="0" x2="150" y2="150" />
        <line x1="235" y1="0" x2="240" y2="150" />
      </g>
      <path d={pathD} fill="none" stroke={COLOR.clay} strokeWidth="5" opacity="0.12" strokeLinecap="round" />
      <path d={pathD} fill="none" stroke={`url(#${id}-route)`} strokeWidth="4" strokeDasharray="1,10" strokeLinecap="round" />
      {/* start pin (agency) */}
      <g transform={`translate(${points[0].x},${points[0].y})`}>
        <circle r="12" fill={COLOR.indigo} />
        <rect x="-5" y="-5" width="10" height="9" fill={COLOR.sand} />
        <rect x="-3" y="-3" width="2" height="2" fill={COLOR.indigo} />
        <rect x="1" y="-3" width="2" height="2" fill={COLOR.indigo} />
      </g>
      {/* end pin (customer) */}
      <g transform={`translate(${points[2].x},${points[2].y})`}>
        <path d="M0,-15 Q13,-15 13,-2 Q13,9 0,18 Q-13,9 -13,-2 Q-13,-15 0,-15 Z" fill={COLOR.saffronDeep} />
        <circle cy="-3" r="5" fill={COLOR.sand} />
      </g>
      {/* the moving car */}
      <g transform={`translate(${pos.x},${pos.y})`} style={{ transition: "transform 1.6s linear" }}>
        <circle r="13" fill="#000" opacity="0.15" />
        <circle r="11" fill={COLOR.saffron} stroke={COLOR.sand} strokeWidth="2" />
        <path d="M-5,2 L-4,-2 Q-3,-4 0,-4 Q3,-4 4,-2 L5,2 Z" fill={COLOR.indigoDeep} />
      </g>
    </svg>
  );
}

// A live "where is this car right now" map for the agency to keep an eye on a vehicle
