// Every car in this fleet is a 2021+ model, so real satellite communication (not just
// GSM) is viable fleet-wide — see the Satellite tracking write-up. This badge marks that
// on any car card; it is a coverage fact about the car, not a live status.
function SatelliteBadge({ size = "sm" }) {
  const { t } = useLang();
  const small = size === "sm";
  return (
    <span
      className={`flex items-center gap-1 rounded-full shrink-0 ${small ? "px-1.5 py-0.5" : "px-2.5 py-1"}`}
      style={{ background: COLOR.tealFaint }}
    >
      <span style={{ fontSize: small ? 10 : 12 }}>🛰️</span>
      <span className={`font-bold ${small ? "text-xs" : "text-xs"}`} style={{ color: COLOR.teal }}>{t("satelliteBadgeLabel")}</span>
    </span>
  );
}

// Full maintenance schedule for one car: insurance, vignette, technical control (date-based)
// plus oil, tires, brakes (mileage-based), each with a computed ok/soon/overdue status.
function CarMaintenanceSheet({ car, onClose }) {
  const { t, lang } = useLang();
  if (!car) return null;
  const schedule = getMaintenanceSchedule(car);
  const statusColor = { ok: COLOR.teal, soon: COLOR.saffronDeep, overdue: COLOR.danger };
  const statusBg = { ok: COLOR.tealFaint, soon: "#FCEFDD", overdue: COLOR.dangerFaint };
  const statusLabel = { ok: "maintStatusOk", soon: "maintStatusSoon", overdue: "maintStatusOverdue" };
  const localeMap = { ar: "ar-MA", fr: "fr-FR", en: "en-US" };

  return (
    <div className="absolute inset-0 flex flex-col" style={{ background: COLOR.sand, zIndex: 40 }}>
      <div className="flex items-center justify-between px-4 py-3" style={{ background: COLOR.white, borderBottom: `1px solid ${COLOR.sandDeep}` }}>
        <button onClick={onClose} className="w-9 h-9 rounded-full flex items-center justify-center" style={{ background: COLOR.sand }}>
          <ChevronRight size={18} color={COLOR.clay} />
        </button>
        <span className="font-bold" style={{ color: COLOR.clay }}>{t("maintenanceScheduleTitle")}</span>
        <div style={{ width: 36 }} />
      </div>

      <div className="flex-1 overflow-y-auto tariq-scroll px-5 py-4">
        <div className="flex items-center gap-3 mb-2">
          <div className="w-14 h-14 rounded-xl flex items-center justify-center shrink-0" style={{ background: COLOR.sandDeep }}>
            <CarSilhouette type={car.type} color={car.color} size={42} />
          </div>
          <div>
            <div className="font-bold text-sm" style={{ color: COLOR.clay }}>{car.name}</div>
            <div className="text-xs" style={{ color: COLOR.clayFaint }}>{car.plate}</div>
          </div>
        </div>
        <div className="mb-4"><SatelliteBadge size="md" /></div>

        <div className="flex flex-col gap-2">
          {schedule.map((item) => (
            <div key={item.key} className="rounded-2xl p-3.5 flex items-center gap-3" style={{ background: COLOR.white, border: `1px solid ${COLOR.sandDeep}` }}>
              <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: statusBg[item.status] }}>
                <item.icon size={16} color={statusColor[item.status]} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-bold" style={{ color: COLOR.clay }}>{t(item.labelKey)}</div>
                <div className="text-xs" style={{ color: COLOR.clayFaint }}>
                  {item.basis === "days"
                    ? item.dueDate.toLocaleDateString(localeMap[lang] || "ar-MA")
                    : `${Math.abs(item.remaining).toLocaleString("en-US")} ${t("kmWord")} ${item.remaining < 0 ? t("overdueBySuffix") : t("remainingSuffix")}`}
                </div>
              </div>
              <span className="text-xs font-bold px-2.5 py-1 rounded-full shrink-0" style={{ background: statusBg[item.status], color: statusColor[item.status] }}>
                {t(statusLabel[item.status])}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// Reusable row for uploading a document photo (ID, license, contract, papers...), with a
// simulated upload delay so it feels real. Used both before delivery (identity) and after
// the driver arrives (contract / car papers).
function DocRow({ icon: Icon = FileText, label, hint, status, onUpload }) {
  return (
    <div className="flex items-center gap-3 py-2.5">
      <div
        className="w-10 h-10 rounded-full flex items-center justify-center shrink-0"
        style={{ background: status === "done" ? COLOR.tealFaint : COLOR.sand }}
      >
        {status === "done" ? <FileCheck2 size={17} color={COLOR.teal} /> : <Icon size={17} color={COLOR.clayFaint} />}
      </div>
      <div className="flex-1 min-w-0">
        <div className="font-bold text-sm" style={{ color: COLOR.clay }}>{label}</div>
        {hint && <div className="text-xs mt-0.5" style={{ color: COLOR.clayFaint }}>{hint}</div>}
      </div>
      {status === "idle" && (
        <button
          onClick={onUpload}
          className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-bold shrink-0"
          style={{ background: COLOR.indigo, color: COLOR.white }}
        >
          <Upload size={12} />
          رفع صورة
        </button>
      )}
      {status === "uploading" && (
        <span className="flex items-center gap-1 text-xs font-bold shrink-0" style={{ color: COLOR.clayFaint }}>
          <Loader2 size={13} className="animate-spin" />
          جاري الرفع
        </span>
      )}
      {status === "done" && (
        <span className="text-xs font-bold shrink-0" style={{ color: COLOR.teal }}>تم الرفع</span>
      )}
    </div>
  );
}

// Lets the customer pick pickup/return days for THIS car and see, day by day, which
// ones are already booked. Tapping a booked day does nothing — it's disabled on purpose.
function AvailabilityCalendar({ bookedDays, pendingDays = [], start, end, onPick }) {
  const days = Array.from({ length: 30 }, (_, i) => i + 1);
  const lo = start && end ? Math.min(start, end) : start;
  const hi = start && end ? Math.max(start, end) : start;
  return (
    <div className="grid grid-cols-7 gap-1.5">
      {days.map((d) => {
        const booked = bookedDays.includes(d);
        const pending = !booked && pendingDays.includes(d);
        const blocked = booked || pending;
        const inRange = start && end && d >= lo && d <= hi;
        const isEndpoint = d === start || d === end;
        return (
          <button
            key={d}
            disabled={blocked}
            onClick={() => onPick(d)}
            className="rounded-lg text-xs font-bold py-2 flex items-center justify-center"
            style={{
              background: booked ? COLOR.sandDeep : pending ? "#FCEFDD" : isEndpoint ? COLOR.indigo : inRange ? COLOR.tealFaint : COLOR.white,
              color: booked ? COLOR.clayFaint : pending ? COLOR.saffronDeep : isEndpoint ? COLOR.white : COLOR.clay,
              textDecoration: blocked ? "line-through" : "none",
              border: `1px solid ${pending ? COLOR.saffronDeep : COLOR.sandDeep}`,
              opacity: blocked ? 0.7 : 1,
              cursor: blocked ? "not-allowed" : "pointer",
            }}
          >
            {d}
          </button>
        );
      })}
    </div>
  );
}

